import{_ as e,a as l,c as n,b as s}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"12-JavaWeb依赖打包问题","description":"","frontmatter":{"title":"12-JavaWeb依赖打包问题"},"headers":[],"relativePath":"posts/开发经验/Spring与Java/12-JavaWeb依赖打包问题.md","filePath":"posts/开发经验/Spring与Java/12-JavaWeb依赖打包问题.md"}'),t={name:"posts/开发经验/Spring与Java/12-JavaWeb依赖打包问题.md"};function i(r,a,p,o,c,d){return l(),n("div",null,[...a[0]||(a[0]=[s(`<h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>在传统 JavaWeb 项目中正确配置了相关的 xml 文件，但是还是无法访问对应的资源</p><p>问题原因：artifact 没有把 Spring 依赖库打包到 WEB-INF/lib/，导致 Tomcat 无法加载 DispatcherServlet。</p><h3 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h3><ol><li>创建了 web/WEB-INF/lib/ 目录 并复制了 50 个 jar 包（排除了 javadoc 和 sources）</li><li>修改了 artifact 配置 (.idea/artifacts/ee_middle_Web_exploded.xml)，让 IntelliJ 知道要把 lib/ 包含进构建产物</li></ol><p>现在在 IntelliJ 中 Rebuild Artifact，然后重启 Tomcat，<a href="http://localhost:8080/index" target="_blank" rel="noreferrer">http://localhost:8080/index</a> 应该就能正常显示了。</p><p>在没有 Maven/Gradle 的传统 Java Web 项目中，确实需要&quot;配置两次&quot;：</p><p>两个阶段的区别</p><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260528151315183.png" alt="image-20260528151315183" referrerpolicy="no-referrer" loading="lazy"></p><p>如何避免重复？</p><p>迁移到 Maven 可以一步解决。只需一个 pom.xml，声明：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>  &lt;groupId&gt;org.springframework&lt;/groupId&gt;</span></span>
<span class="line"><span>  &lt;artifactId&gt;spring-webmvc&lt;/artifactId&gt;</span></span>
<span class="line"><span>  &lt;version&gt;4.3.2.RELEASE&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><p>Maven 会自动：</p><ul><li>让 IntelliJ 识别依赖（编译时）</li><li>打包进 WEB-INF/lib/（运行时）</li></ul><p>你现在的情况</p><p>刚才我已经帮你把 jar 从 ../libs/ 复制到了 web/WEB-INF/lib/，编译时依赖（.iml）本来就已经指向 ../libs/，所以你现在：</p><ul><li>不需要再手动拖任何东西，两边的 lib 依赖都已就绪</li><li>只需要在 IntelliJ 里 Rebuild Artifact，然后重启 Tomcat 即可</li></ul>`,17)])])}const g=e(t,[["render",i]]);export{u as __pageData,g as default};
